    int n, m, md;
    cin >> n >> m >> md;
    vector<unsigned long long> fac(n + 1, 1), inv(n + 1, 1), f(n + 1, 0), g(n + 1, 1);
    for (int i = 1; i <= n; ++i) {
        fac[i] = fac[i - 1] * i % md;
    }
    auto fpow = [&](int x, int y) {
        unsigned long long res = 1, base = x;
        while (y > 0) {
            if (y & 1) res = res * base % md;
            base = base * base % md;
            y >>= 1;
        }
        return res;
    };
    inv[n] = fpow(fac[n], md - 2);
    for (int i = n; i >= 1; --i) {
        inv[i - 1] = inv[i] * i % md;
    }
    auto C = [&](int n, int r) {
        return fac[n] * inv[r] % md * inv[n - r] % md;
    };
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= i; ++j) {
            int now = (int)(C(i - 1, j - 1) * (long long)(i + 1) % md);
            g[i] = (g[i] + (long long)g[j - 1] * g[i - j] % md * now) % md;
            f[i] = (f[i] + (long long)f[j - 1] * g[i - j] % md * now) % md;
            f[i] = (f[i] + (long long)g[j - 1] * f[i - j] % md * now) % md;
            int add_val = ((j - 1) * j / 2 + (i - j) * (i - j + 1) / 2);
            f[i] = (f[i] + (long long)C(i - 1, j - 1) * g[j - 1] % md * g[i - j] % md * add_val) % md;
        }
    }
    vector<vector<vector<int>>> dp(n + 1, vector<vector<int>>(m + 1, vector<int>(2, 0)));
    vector<vector<vector<int>>> dp2(n + 1, vector<vector<int>>(m + 1, vector<int>(2, 0)));
    dp[0][0][1] = 0; dp2[0][0][1] = 1;
    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j <= i; ++j) {
            dp[i][j][1] = (dp[i - 1][j][0] + dp[i - 1][j][1]) % md;
            dp2[i][j][1] = (dp2[i - 1][j][0] + dp2[i - 1][j][1]) % md;
            for (int k = 1; k <= j; ++k) {
                int c = (int)(C(j, k));
                int val1 = (int)((long long)dp2[i - k][j - k][1] * f[k] % md);
                int val2 = (int)((long long)dp[i - k][j - k][1] * g[k] % md);
                dp[i][j][0] = (dp[i][j][0] + (long long)c * val1) % md;
                dp[i][j][0] = (dp[i][j][0] + (long long)c * val2) % md;
                dp2[i][j][0] = (dp2[i][j][0] + (long long)c * val2) % md;
            }
        }
    }
    cout << (dp[n][m][0] + dp[n][m][1]) % md << "\n";
    return 0;
